schema.schemaSDL:
type Query {
  product(id: ID!): Product
  products: [Product]
}

type Mutation {
  submitOrder(orderInput: OrderInput!): OrderConfirmation
}

type Product {
  id: ID!
  name: String!
  price: Float!
  availability: Int!
}

input OrderInput {
  productId: ID!
  quantity: Int!
  shippingAddress: AddressInput!
}

input AddressInput {
  street: String!
  city: String!
  postalCode: String!
  country: String!
}

 type OrderConfirmation {
  orderId: ID!
  estimatedDelivery: String!
}

queries.query:
query {
  products {
    id
    name
    price
    availability
  }
}

mutations.mutation:
mutation {
  submitOrder(orderInput: {
    productId: "102",
    quantity: 2,
    shippingAddress: {
      street: "123 Main St",
      city: "Anytown",
      postalCode: "12345",
      country: "USA"
    }
  }) {
    orderId
    estimatedDelivery
  }
}
